      "content": "{\n  \"name\": \"@anweat/dsh-browser\",\n  \"version\": \"0.2.3\",\n  \"description\": \"Browser runtime plugin for DeepSeek Harness (scoped @anweat) — ships Playwright and Patchright, uses your system Chrome / Edge (or a Playwright Chromium you install), optionally drives OpenCLI site adapters, exposes a `browser` service and interactive browser tools.\",\n  \"license\": \"MIT\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"types\": \"lib/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": {\n      \"types\": \"./lib/client/index.d.ts\",\n      \"default\": \"./lib/client.js\"\n    },\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib\",\n    \"assets\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"README.en.md\",\n    \"CHANGELOG.md\",\n    \"AUDIT.md\",\n    \"scripts\",\n    \"LICENSE\"\n  ],\n  \"engines\": {\n    \"node\": \"^22.19 || >=24\"\n  },\n  \"scripts\": {\n    \"build\": \"node scripts/clean-lib.mjs && tsc -p tsconfig.json && tsdown\",\n    \"typecheck\": \"tsc -p tsconfig.json --noEmit\",\n    \"test\": \"node --import ./test/isolate-home.mjs --test --experimental-transform-types test/*.test.ts\",\n    \"test:e2e\": \"node --import ./test/isolate-home.mjs --test --experimental-transform-types test/e2e/*.test.ts\",\n    \"measure:tools\": \"node scripts/measure-tool-surface.mjs\",\n    \"prompts:dump\": \"node scripts/dump-prompts.mjs\",\n    \"test:client-bundle\": \"node scripts/check-client-bundle.mjs\",\n    \"verify\": \"pnpm run typecheck && pnpm run test:peers && pnpm run build && pnpm test && pnpm run test:client-bundle && pnpm run docs:check\",\n    \"prepublishOnly\": \"pnpm run verify\",\n    \"prepare\": \"npm run build\",\n    \"test:peers\": \"node test/compat/check-peer-ranges.js\",\n    \"docs:check\": \"node scripts/check-docs-links.mjs\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"~4.0.4 || ~4.1.0\",\n    \"@deepseek-ai/dsh-tools\": \">=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-rc.2 <0.2.2-0 || >=0.2.2-rc.1 <0.2.3-0\",\n    \"@deepseek-ai/dsh-client-connection\": \">=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-rc.2 <0.2.2-0 || >=0.2.2-rc.1 <0.2.3-0\",\n    \"@deepseek-ai/dsh-client-locale\": \">=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-rc.2 <0.2.2-0 || >=0.2.2-rc.1 <0.2.3-0\",\n    \"@deepseek-ai/dsh-client-store\": \">=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-rc.2 <0.2.2-0 || >=0.2.2-rc.1 <0.2.3-0\",\n    \"@deepseek-ai/dsh-client-ui-renderer\": \">=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-rc.2 <0.2.2-0 || >=0.2.2-rc.1 <0.2.3-0\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \">=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-rc.2 <0.2.2-0 || >=0.2.2-rc.1 <0.2.3-0\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \">=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-rc.2 <0.2.2-0 || >=0.2.2-rc.1 <0.2.3-0\",\n    \"@deepseek-ai/dsh-client-ui-plugin-manager\": \">=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-rc.2 <0.2.2-0 || >=0.2.2-rc.1 <0.2.3-0\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \">=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-rc.2 <0.2.2-0 || >=0.2.2-rc.1 <0.2.3-0\",\n    \"@deepseek-ai/dsh-settings\": \">=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-rc.2 <0.2.2-0 || >=0.2.2-rc.1 <0.2.3-0\",\n    \"@deepseek-ai/schemastery\": \">=3.18.2 <4\",\n    \"@jackwener/opencli\": \">=1.8.0 <2\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/cordis\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-tools\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-connection\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-locale\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-store\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-renderer\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-settings\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-primitives\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-plugin-manager\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-slots\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-settings\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/schemastery\": {\n      \"optional\": true\n    },\n    \"@jackwener/opencli\": {\n      \"optional\": true\n    }\n  },\n  \"dependencies\": {\n    \"patchright\": \"^1.62.1\",\n    \"playwright\": \"^1.60.0\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"4.1.0\",\n    \"@deepseek-ai/dsh-agent\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-llm\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-scope\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-session\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-session-projection\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-system-prompt\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-user-approval\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-tools\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-connection\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-locale\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-store\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-renderer\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-settings\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/schemastery\": \"3.18.5\",\n    \"@types/react\": \"~18.3.1\",\n    \"@types/react-dom\": \"~18.3.1\",\n    \"react\": \"^18.2.0\",\n    \"react-dom\": \"18.2.0\",\n    \"tsdown\": \"^0.22.2\",\n    \"typescript\": \"^5.6.0\",\n    \"@types/node\": \"^22.0.0\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-plugin-manager\": \"0.2.2-rc.1\",\n    \"clsx\": \"^2.0.0\",\n    \"@deepseek-ai/dsh-working-directory\": \"0.2.2-rc.1\",\n    \"@jackwener/opencli\": \"^1.8.7\"\n  },\n  \"dsh\": {\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-connection\",\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-renderer\",\n        \"@deepseek-ai/dsh-client-ui-settings\",\n        \"@deepseek-ai/dsh-client-ui-plugin-manager\"\n      ],\n      \"platform\": \"web\"\n    },\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    }\n  },\n  \"packageManager\": \"pnpm@11.7.0\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/anweat/dsh-browser.git\"\n  },\n  \"keywords\": [\n    \"dsh\",\n    \"deepseek-harness\",\n    \"plugin\",\n    \"browser\",\n    \"playwright\",\n    \"opencli\"\n  ]\n}\n"
